import{_ as a,o as r,c as l,a2 as d}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"住房保障法","description":"","frontmatter":{},"headers":[],"relativePath":"zh/45-住房保障法.md","filePath":"zh/45-住房保障法.md"}'),i={name:"zh/45-住房保障法.md"};function o(e,t,n,h,s,u){return r(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="住房保障法" tabindex="-1">住房保障法 <a class="header-anchor" href="#住房保障法" aria-label="Permalink to &quot;住房保障法&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文档编号</td><td>45</td></tr><tr><td>所属模块</td><td>法律体系与治理框架</td></tr><tr><td>核心关键词</td><td>居住权、保障性住房、空间法理、宜居环境、反投机</td></tr></tbody></table><h2 id="一、立法目的与基本原则" tabindex="-1">一、立法目的与基本原则 <a class="header-anchor" href="#一、立法目的与基本原则" aria-label="Permalink to &quot;一、立法目的与基本原则&quot;">​</a></h2><p>《住房保障法》是锚点共生文明五部配套法之一，旨在保障衡元宙内一切生命的居住权，建立公平、可持续的住房保障体系，利用空间法理调度技术为万族提供适宜的居住空间，防止住房领域的投机与掠夺。</p><p>本法确立以下基本原则：</p><table tabindex="0"><thead><tr><th>原则</th><th>内涵</th></tr></thead><tbody><tr><td>居住保障原则</td><td>每个生命都有权获得适宜的居住空间，国家与文明有义务保障基本居住需求</td></tr><tr><td>公益优先原则</td><td>住房首先是生活必需品而非投机商品，保障性住房具有公益属性</td></tr><tr><td>空间高效原则</td><td>利用空间法理调度技术提高空间利用效率，拓展宜居空间</td></tr><tr><td>异族适配原则</td><td>针对不同种族的生理特性与生活习惯提供适配的居住空间</td></tr><tr><td>宜居环境原则</td><td>居住空间应当具备良好的生态环境、基础设施与公共服务</td></tr><tr><td>反投机原则</td><td>禁止以住房为标的进行投机炒作，防止住房成为掠夺财富的工具</td></tr></tbody></table><h2 id="二、居住权的法律保障" tabindex="-1">二、居住权的法律保障 <a class="header-anchor" href="#二、居住权的法律保障" aria-label="Permalink to &quot;二、居住权的法律保障&quot;">​</a></h2><p>本法明确规定，居住权是共生宪法赋予每个生命的基本权利，具体包括：</p><ol><li><strong>基本居住权</strong>：每个生命有权获得不低于最低标准的居住空间，最低标准根据种族体型与生活需求确定。</li><li><strong>住房保障申请权</strong>：符合条件的生命有权申请保障性住房，申请条件与分配标准公开透明。</li><li><strong>居住安全权</strong>：居住空间应当符合安全标准，危房与不适宜居住的空间不得出租或分配。</li><li><strong>居住稳定权</strong>：保障性住房的居住者在符合条件的情况下享有稳定的居住权，不得被随意驱逐。</li><li><strong>居住环境权</strong>：居住者有权获得清洁的空气、水源与良好的周边环境，有权对环境污染提出投诉。</li><li><strong>住房改造权</strong>：居住者有权在不影响建筑安全与他人权益的前提下，对居住空间进行合理改造。</li></ol><h2 id="三、住房保障体系" tabindex="-1">三、住房保障体系 <a class="header-anchor" href="#三、住房保障体系" aria-label="Permalink to &quot;三、住房保障体系&quot;">​</a></h2><p>锚点共生文明的住房保障体系分为三类住房，覆盖不同需求层次：</p><table tabindex="0"><thead><tr><th>类型</th><th>名称</th><th>保障对象</th><th>分配方式</th><th>租金/价格</th></tr></thead><tbody><tr><td>第一类</td><td>公共租赁住房</td><td>低收入群体、初级修炼者、新移民</td><td>申请审核制，轮候分配</td><td>象征性低租金</td></tr><tr><td>第二类</td><td>共有产权住房</td><td>中等收入群体、中级修炼者</td><td>申请审核制，摇号分配</td><td>低于市场价，个人与国家共有产权</td></tr><tr><td>第三类</td><td>商品住房</td><td>高收入群体、高阶修炼者</td><td>市场交易</td><td>市场价格，受调控约束</td></tr></tbody></table><p>此外，利用空间法理调度技术建设&quot;折叠空间居住区&quot;：在有限的物理空间内通过空间折叠技术拓展居住面积，为高密度区域提供更多居住空间。折叠空间居住区必须经过安全评估，确保空间稳定性。</p><h2 id="四、异族住房适配" tabindex="-1">四、异族住房适配 <a class="header-anchor" href="#四、异族住房适配" aria-label="Permalink to &quot;四、异族住房适配&quot;">​</a></h2><p>针对衡元宙内不同种族的特殊居住需求，本法设立异族住房适配制度：</p><ul><li><strong>水生种族</strong>：提供水下居住空间或水陆两栖住宅，配备水循环与水质维护系统。</li><li><strong>飞行种族</strong>：提供高空居住空间或带起降平台的住宅，配备空中交通管理。</li><li><strong>能量生命</strong>：提供能量浓度适宜的居住空间，配备能量稳定装置。</li><li><strong>巨型种族</strong>：提供大尺度居住空间，建筑结构经过特殊加固。</li><li><strong>微型种族</strong>：提供微型居住区，配备缩放通道与专用设施。</li></ul><p>异族住房适配标准由住房主管部门会同各族代表共同制定，定期更新。</p><h2 id="五、住房建设与管理" tabindex="-1">五、住房建设与管理 <a class="header-anchor" href="#五、住房建设与管理" aria-label="Permalink to &quot;五、住房建设与管理&quot;">​</a></h2><ul><li><strong>住房建设规划</strong>：国家根据人口增长与移民情况制定住房建设规划，确保住房供给与需求平衡。</li><li><strong>建设标准</strong>：保障性住房的建设必须符合安全、环保、宜居标准，禁止降低建设质量。</li><li><strong>物业管理</strong>：居住区实行自治管理与专业物业相结合的模式，居住者有权参与物业管理决策。</li><li><strong>住房维修</strong>：保障性住房的维修由住房管理机构负责，维修资金从公共积累中列支。</li><li><strong>退出机制</strong>：保障性住房居住者的收入或修为超过保障标准的，应当退出保障性住房或转为商品住房，退出给予合理过渡期。</li></ul><h2 id="六、反投机与监管" tabindex="-1">六、反投机与监管 <a class="header-anchor" href="#六、反投机与监管" aria-label="Permalink to &quot;六、反投机与监管&quot;">​</a></h2><p>为防止住房领域的投机与掠夺，本法设立以下监管措施：</p><ol><li>限制个人持有商品住房的数量，超过限额的征收累进房产税。</li><li>禁止保障性住房的转租与倒卖，违者取消保障资格并追回住房。</li><li>建立住房交易信息公开制度，防止暗箱操作与价格操纵。</li><li>对房地产开发商实行资质管理与资金监管，防止烂尾与欺诈。</li><li>设立住房投诉与纠纷解决机制，保障居住者合法权益。</li></ol><h2 id="七、法律责任" tabindex="-1">七、法律责任 <a class="header-anchor" href="#七、法律责任" aria-label="Permalink to &quot;七、法律责任&quot;">​</a></h2><p>违反本法规定的行为，视情节轻重承担以下责任：</p><ul><li>违规分配保障性住房的，责令纠正并对责任人给予处分。</li><li>转租、倒卖保障性住房的，取消保障资格、追回住房并处罚款。</li><li>开发商降低建设质量的，责令返工并处罚款，情节严重的吊销资质。</li><li>住房投机炒作的，征收高额投机税并处罚款。</li><li>危房出租造成居住者损害的，承担赔偿责任，情节严重的追究刑事责任。</li></ul><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>《住房保障法》是锚点共生文明&quot;人人有路&quot;理念在居住领域的落实。它通过建立分类住房保障体系、利用空间法理技术拓展居住空间、适配异族居住需求、打击住房投机，确保每个生命都能拥有一个安全、适宜、稳定的家，为万族共进提供安居保障。</p><h2 id="关联文档" tabindex="-1">关联文档 <a class="header-anchor" href="#关联文档" aria-label="Permalink to &quot;关联文档&quot;">​</a></h2><ul><li>40-共生宪法总纲</li><li>39-住房与环境保障</li><li>13-空间法理调度体系详解</li><li>46-环境保护法</li></ul>',29)])])}const g=a(i,[["render",o]]);export{c as __pageData,g as default};
